function clubMigrationSportsAdapters():array {
 $out=[];foreach(['person','trainer','account','team','family_role','roster','program','training','event','result','measurement'] as $type)$out[$type]=[
  'authorize'=>static function(PDO $p,int $a)use($type):void {clubMigrationActor($p,$a,in_array($type,['person','family_role','roster','program','trainer','account','team'],true)?['registrar']:['sports_lead']);if($type==='trainer'){$q=$p->prepare('SELECT trainer_id FROM staff_superadmins WHERE trainer_id=?'.accountingLedgerLock($p));$q->execute([$a]);if(!$q->fetchColumn())throw new DomainException('Mapu pracovníků potvrzuje pověřený správce.');}},
  'preview'=>'clubMigrationSportsPreview','apply'=>'clubMigrationSportsApply','target'=>'clubMigrationSportsTarget'];return $out;
