function clubMigrationSportsRow(PDO $p,string $table,int $id):array {$q=$p->prepare('SELECT * FROM '.$table.' WHERE id=?'.($p->inTransaction()?accountingLedgerLock($p):''));$q->execute([$id]);$row=$q->fetch(PDO::FETCH_ASSOC);if(!$row)throw new DomainException('Cílová položka neexistuje.');return $row;}
