 if($type==='team')$out['season']=clubMigrationSportsRow($p,'club_seasons',(int)$row['season_id']);
 if($type==='account'){$out['row']=array_intersect_key($row,array_flip(['id','jmeno','prijmeni','email','email_overeno','aktivni']));$q=$p->prepare("SELECT sportovec_id,relation_role,status,valid_from,valid_to FROM account_person_roles WHERE account_id=? AND relation_role='self' ORDER BY id".($p->inTransaction()?accountingLedgerLock($p):''));$q->execute([$id]);$out['self_links']=$q->fetchAll(PDO::FETCH_ASSOC);}
 if($type==='training') {foreach(['trenink_sportovec'=>'sportovec_id','trenink_trener'=>'trener_id'] as $t=>$field){$q=$p->prepare('SELECT '.$field.' FROM '.$t.' WHERE trenink_id=? ORDER BY '.$field.($p->inTransaction()?accountingLedgerLock($p):''));$q->execute([$id]);$out[$t]=$q->fetchAll(PDO::FETCH_COLUMN);} $q=$p->prepare('SELECT c.*,r.snapshot_json FROM training_closures c JOIN training_closure_revisions r ON r.id=c.current_revision_id WHERE c.training_id=?'.($p->inTransaction()?accountingLedgerLock($p):''));$q->execute([$id]);$out['closure']=$q->fetch(PDO::FETCH_ASSOC)?:null;}
