function clubMigrationResolve(PDO $p,array $batch,string $type,string $sourceId):array {
 $map=clubMigrationMap($p,$batch['source_namespace'],$type,clubMigrationKey($sourceId));if(!$map)throw new DomainException('Chybí převzatá a potvrzená mapa '.$type.':'.$sourceId.'.');$adapter=clubMigrationAdapter($type);$target=($adapter['target'])($p,$map['target_type'],(int)$map['target_id']);if(!hash_equals($map['target_hash'],clubMigrationHash($target)))throw new DomainException('Mapovaný cíl '.$type.':'.$sourceId.' se změnil.');return ['id'=>(int)$map['target_id'],'hash'=>$map['target_hash']];
}
function clubMigrationSportsExactLink(PDO $p,string $type,int $id,array $n):array {
 $t=clubMigrationSportsTarget($p,$type,$id);$r=$t['row'];$same=false;
 if($type==='training'){$closure=$t['closure'];$s=$closure?json_decode($closure['snapshot_json'],true,64,JSON_THROW_ON_ERROR):[];$people=array_map('intval',array_column($n['maps']['participant_source_ids']??[],'id'));sort($people);$coaches=array_map('intval',array_column($n['maps']['coach_source_ids']??[],'id'));sort($coaches);$actualPeople=array_map('intval',$t['trenink_sportovec']);sort($actualPeople);$actualCoaches=array_map('intval',$t['trenink_trener']);sort($actualCoaches);$snapshotPeople=array_map('intval',$s['participant_ids']??[]);sort($snapshotPeople);$snapshotCoaches=array_map('intval',$s['coach_ids']??[]);sort($snapshotCoaches);$same=($closure['status']??'')==='closed'&&($s['actual_started_at']??'')===$n['started_at']&&($s['actual_ended_at']??'')===$n['ended_at']&&(int)($s['duration_minutes']??0)===$n['minutes']&&$r['napln']===$n['label']&&$r['kategorie']===$n['category']&&$actualPeople===$people&&$actualCoaches===$coaches&&$snapshotPeople===$people&&$snapshotCoaches===$coaches;}
 elseif($type==='event'){$q=$p->prepare('SELECT starts_at FROM club_event_sessions WHERE event_id=? ORDER BY starts_at'.($p->inTransaction()?accountingLedgerLock($p):''));$q->execute([$id]);$dates=array_map(static fn($d)=>substr((string)$d,0,10),$q->fetchAll(PDO::FETCH_COLUMN));$same=$r['name']===$n['label']&&$r['activity_kind']===$n['activity_kind']&&(in_array($n['date'],$dates,true)||str_contains((string)($r['internal_note']??''),'Zdrojové datum '.$n['date'].';'));}
 elseif($type==='result'){$s=json_decode($r['snapshot_json'],true,64,JSON_THROW_ON_ERROR);$same=(int)$t['participation']['current_revision_id']===$id&&(int)$t['participation']['event_id']===$n['maps']['event']['id']&&(int)$t['participation']['sportovec_id']===$n['maps']['person']['id'];foreach(['stage','actual_date','result_status','result_value','result_unit'] as $field)$same=$same&&($s[$field]??null)===($n[$field]??null);}
 elseif($type==='measurement'){$same=(int)$r['sportovec_id']===$n['maps']['person']['id']&&$r['typ']===$n['kind']&&in_array($n['maps']['training']['id'],array_map('intval',$t['training_ids']),true);foreach(['vzdalenost'=>'distance','distance_unit'=>'unit','distance_meters'=>'meters','cas'=>'time','duration_ms'=>'duration_ms','rpe'=>'rpe','rpe_value'=>'rpe_value'] as $field=>$key){if($r[$field]===null||$n[$key]===null)$same=$same&&$r[$field]===$n[$key];elseif(in_array($field,['vzdalenost','distance_meters','duration_ms','rpe_value'],true))$same=$same&&(float)$r[$field]===(float)$n[$key];else $same=$same&&(string)$r[$field]===(string)$n[$key];}}
 if(!$same)throw new DomainException('Existující aktivita neodpovídá přesným ověřeným podkladům. Vyžaduje individuální posouzení; nebude přepsána.');return $t;
}
